    private void verifyHttpDeliveryRetry(String token,String secret)throws Exception{
        var calls=new java.util.concurrent.atomic.AtomicInteger();var sideEffects=java.util.concurrent.ConcurrentHashMap.<String>newKeySet();var signedRequests=new java.util.concurrent.atomic.AtomicBoolean(true);var server=com.sun.net.httpserver.HttpServer.create(new java.net.InetSocketAddress("127.0.0.1",0),0);
        server.createContext("/normalized-events",exchange->{try{String requestBody=new String(exchange.getRequestBody().readAllBytes(),StandardCharsets.UTF_8),key=exchange.getRequestHeaders().getFirst("X-Idempotency-Key"),timestamp=exchange.getRequestHeaders().getFirst("X-Timestamp"),signature=exchange.getRequestHeaders().getFirst("X-Signature"),source=exchange.getRequestHeaders().getFirst("X-Source-System"),signatureVersion=exchange.getRequestHeaders().getFirst("X-Signature-Version");if(key!=null)sideEffects.add(key);try{signedRequests.compareAndSet(true,key!=null&&timestamp!=null&&"REMOTE_503".equals(source)&&"RDP-HMAC-V1".equals(signatureVersion)&&hmac(secret,"RDP-HMAC-V1\nPOST\n/normalized-events\n"+source+"\n"+timestamp+"\n"+key+"\n"+requestBody).equals(signature));}catch(Exception ex){signedRequests.set(false);}int call=calls.incrementAndGet();if(call==1)exchange.getResponseHeaders().set("Retry-After","60");if(call==2)exchange.getResponseHeaders().set("Retry-After",java.time.ZonedDateTime.now(java.time.ZoneOffset.UTC).plusSeconds(300).format(java.time.format.DateTimeFormatter.RFC_1123_DATE_TIME));exchange.sendResponseHeaders(call<=3?503:204,-1);}finally{exchange.close();}});server.start();
        try{
            assertEquals(400,request(HttpMethod.POST,"/api/integrations",token,Map.of("systemCode","REMOTE_BLOCKED","systemName","白名单拒绝验证","systemType","OTHER","authType","HMAC","secret",secret,"active",true,"config",Map.of("ipWhitelist",java.util.List.of("127.0.0.1"),"deliveryMode","HTTP","deliveryUrl","https://not-allowed.invalid/events"))).getStatusCode().value());
            Map<String,Object> options=Map.ofEntries(Map.entry("ipWhitelist",java.util.List.of("127.0.0.1")),Map.entry("trustDomain","REMOTE_DELIVERY"),Map.entry("entityType","EVENT"),Map.entry("recordKeyField","id"),Map.entry("sourceVersionField","version"),Map.entry("sourcePriority",80),Map.entry("deliveryMode","HTTP"),Map.entry("deliveryUrl","http://127.0.0.1:"+server.getAddress().getPort()+"/normalized-events"),Map.entry("deliveryTimeoutMillis",2000),Map.entry("maxRetries",4),Map.entry("retryDelaysSeconds",java.util.List.of(60,300,1800)));
            ResponseEntity<JsonNode> config=request(HttpMethod.POST,"/api/integrations",token,Map.of("systemCode","REMOTE_503","systemName","HTTP 503退避验证","systemType","OTHER","authType","HMAC","secret",secret,"active",true,"config",options));assertEquals(200,config.getStatusCode().value(),String.valueOf(config.getBody()));long integrationId=config.getBody().at("/data/id").asLong();assertEquals(200,request(HttpMethod.PUT,"/api/integrations/"+integrationId+"/mappings?expectedMappingVersion=1",token,java.util.List.of()).getStatusCode().value());
            String key="remote-"+UUID.randomUUID(),timestamp=Long.toString(Instant.now().getEpochSecond()),body="{\"id\":\"REMOTE-1\",\"version\":1,\"event\":\"normalized\"}";ResponseEntity<JsonNode> accepted=rest.exchange("/api/integrations/webhook/REMOTE_503",HttpMethod.POST,new HttpEntity<>(body,webhookHeaders(timestamp,key,integrationHmac(secret,"REMOTE_503",timestamp,key,body))),JsonNode.class);assertEquals(202,accepted.getStatusCode().value());long jobId=accepted.getBody().at("/data/jobId").asLong();
            integrationService.retryDue();long letterId=jdbc.sql("SELECT id FROM integration_dead_letter WHERE job_id=:job").param("job",jobId).query(Long.class).single();assertTrue(jdbc.sql("SELECT local_committed AND delivery_status='PENDING' FROM integration_job WHERE id=:id").param("id",jobId).query(Boolean.class).single());assertNotNull(jdbc.sql("SELECT delivery_secret_ciphertext FROM integration_job WHERE id=:id").param("id",jobId).query(String.class).single());assertEquals(1,jdbc.sql("SELECT count(*) FROM integration_processed_record WHERE trust_domain='REMOTE_DELIVERY' AND entity_type='EVENT' AND record_key='REMOTE-1' AND job_id=:job").param("job",jobId).query(Long.class).single());assertEquals("REMOTE_RETRYABLE",jdbc.sql("SELECT error_category FROM integration_job WHERE id=:id").param("id",jobId).query(String.class).single());assertTrue(jdbc.sql("SELECT next_retry_time BETWEEN now()+interval '50 seconds' AND now()+interval '70 seconds' FROM integration_dead_letter WHERE id=:id").param("id",letterId).query(Boolean.class).single());
            JsonNode pendingReconcile=request(HttpMethod.POST,"/api/integrations/"+integrationId+"/reconcile",token,Map.of()).getBody().at("/data");assertEquals(1,pendingReconcile.path("matched").asInt());assertEquals(1,pendingReconcile.path("deliveryPending").asInt());String newerKey="remote-newer-"+UUID.randomUUID(),newerTime=Long.toString(Instant.now().getEpochSecond()),newerBody="{\"id\":\"REMOTE-1\",\"version\":2,\"event\":\"must-wait\"}";long newerJob=rest.exchange("/api/integrations/webhook/REMOTE_503",HttpMethod.POST,new HttpEntity<>(newerBody,webhookHeaders(newerTime,newerKey,integrationHmac(secret,"REMOTE_503",newerTime,newerKey,newerBody))),JsonNode.class).getBody().at("/data/jobId").asLong();integrationService.retryDue();assertEquals("DELIVERY_GAP",jdbc.sql("SELECT error_category FROM integration_job WHERE id=:id").param("id",newerJob).query(String.class).single());assertEquals(1,calls.get(),"同一实体的较新事件必须等待前序远端交付完成");
            ResponseEntity<JsonNode> deliveryReplay=request(HttpMethod.POST,"/api/integrations/dead-letters/"+letterId+"/retry",token,Map.of("note","刷新当前HTTP交付参数后后台重放","useCurrentMapping",true));assertEquals(202,deliveryReplay.getStatusCode().value());assertEquals("PENDING",deliveryReplay.getBody().at("/data/status").asText());integrationService.retryDue();assertTrue(jdbc.sql("SELECT next_retry_time BETWEEN now()+interval '280 seconds' AND now()+interval '320 seconds' FROM integration_dead_letter WHERE id=:id AND retry_count=1").param("id",letterId).query(Boolean.class).single());String rotatedSecret="rotated-integration-hmac-secret-2026-abcdef";assertEquals(200,request(HttpMethod.PUT,"/api/integrations/"+integrationId,token,Map.of("systemCode","REMOTE_503","systemName","HTTP 503退避验证","systemType","OTHER","authType","HMAC","secret",rotatedSecret,"active",true,"config",options,"expectedVersion",2)).getStatusCode().value());String rotationBody="{\"id\":\"ROTATION-CHECK\",\"version\":1}",rotationKey="rotation-"+UUID.randomUUID(),rotationTime=Long.toString(Instant.now().getEpochSecond());assertEquals(401,rest.exchange("/api/integrations/webhook/REMOTE_503",HttpMethod.POST,new HttpEntity<>(rotationBody,webhookHeaders(rotationTime,rotationKey,integrationHmac(secret,"REMOTE_503",rotationTime,rotationKey,rotationBody))),JsonNode.class).getStatusCode().value());ResponseEntity<JsonNode> rotatedAccepted=rest.exchange("/api/integrations/webhook/REMOTE_503",HttpMethod.POST,new HttpEntity<>(rotationBody,webhookHeaders(rotationTime,rotationKey,integrationHmac(rotatedSecret,"REMOTE_503",rotationTime,rotationKey,rotationBody))),JsonNode.class);assertEquals(202,rotatedAccepted.getStatusCode().value());jdbc.sql("UPDATE integration_job SET status='SKIPPED',delivery_secret_ciphertext=NULL WHERE id=:id").param("id",rotatedAccepted.getBody().at("/data/jobId").asLong()).update();
            jdbc.sql("UPDATE integration_dead_letter SET next_retry_time=now()-interval '1 second' WHERE id=:id").param("id",letterId).update();integrationService.retryDue();assertTrue(jdbc.sql("SELECT next_retry_time BETWEEN now()+interval '1750 seconds' AND now()+interval '1850 seconds' FROM integration_dead_letter WHERE id=:id AND retry_count=2").param("id",letterId).query(Boolean.class).single());
            jdbc.sql("UPDATE integration_dead_letter SET next_retry_time=now()-interval '1 second' WHERE id=:id").param("id",letterId).update();integrationService.retryDue();assertEquals("COMPLETED",jdbc.sql("SELECT status FROM integration_job WHERE id=:id").param("id",jobId).query(String.class).single());assertEquals("COMPLETED",jdbc.sql("SELECT delivery_status FROM integration_job WHERE id=:id").param("id",jobId).query(String.class).single());assertEquals(0,jdbc.sql("SELECT count(*) FROM integration_job WHERE id=:id AND delivery_secret_ciphertext IS NOT NULL").param("id",jobId).query(Long.class).single());assertEquals("RESOLVED",jdbc.sql("SELECT status FROM integration_dead_letter WHERE id=:id").param("id",letterId).query(String.class).single());assertEquals(4,calls.get());assertEquals(1,sideEffects.size());assertTrue(signedRequests.get());assertEquals(3,jdbc.sql("SELECT count(*) FROM integration_retry_attempt WHERE dead_letter_id=:id AND length(mapping_snapshot_digest)=64 AND length(processing_config_digest)=64 AND mapping_version=2").param("id",letterId).query(Long.class).single());
            Map<String,Object> lowOptions=new java.util.LinkedHashMap<>(options);lowOptions.put("sourcePriority",10);ResponseEntity<JsonNode> lowConfig=request(HttpMethod.POST,"/api/integrations",token,Map.of("systemCode","REMOTE_LOW","systemName","低优先级远端来源","systemType","OTHER","authType","HMAC","secret",secret,"active",true,"config",lowOptions));long lowId=lowConfig.getBody().at("/data/id").asLong();assertEquals(200,request(HttpMethod.PUT,"/api/integrations/"+lowId+"/mappings?expectedMappingVersion=1",token,java.util.List.of()).getStatusCode().value());String lowKey="remote-low-"+UUID.randomUUID(),lowTime=Long.toString(Instant.now().getEpochSecond()),lowBody="{\"id\":\"REMOTE-1\",\"version\":999,\"event\":\"must-not-deliver\"}";long lowJob=rest.exchange("/api/integrations/webhook/REMOTE_LOW",HttpMethod.POST,new HttpEntity<>(lowBody,webhookHeaders(lowTime,lowKey,integrationHmac(secret,"REMOTE_LOW",lowTime,lowKey,lowBody))),JsonNode.class).getBody().at("/data/jobId").asLong();integrationService.retryDue();assertEquals("SKIPPED",jdbc.sql("SELECT status FROM integration_job WHERE id=:id").param("id",lowJob).query(String.class).single());assertEquals(4,calls.get(),"信任源裁决未接受的事件不得调用远端");
        }finally{server.stop(0);}
    }

    private boolean jsonArrayContains(JsonNode array,String field,String value){for(JsonNode item:array)if(value.equals(item.path(field).asText()))return true;return false;}
    private long jsonArrayId(JsonNode array,String field,String value){return jsonArrayObject(array,field,value).path("id").asLong();}
    private JsonNode jsonArrayObject(JsonNode array,String field,Object value){for(JsonNode item:array)if(String.valueOf(value).equals(item.path(field).asText()))return item;fail("Missing "+field+"="+value+" in "+array);return mapper.createObjectNode();}

    private JsonNode login(String password){return login("admin",password);}
    private JsonNode login(String username,String password){JsonNode captcha=rest.getForObject("/api/auth/captcha",JsonNode.class);String key=captcha.at("/data/captchaKey").asText(),answer=redis.opsForValue().get("captcha:"+key);ResponseEntity<JsonNode> response=rest.postForEntity("/api/auth/login",Map.of("username",username,"password",password,"captchaKey",key,"captchaCode",answer),JsonNode.class);assertEquals(200,response.getStatusCode().value());return response.getBody();}
    private ResponseEntity<JsonNode> loginResponse(String username,String password){Map<String,String> captcha=captchaAnswer();return anonymousJson(HttpMethod.POST,"/api/auth/login",Map.of("username",username,"password",password,"captchaKey",captcha.get("key"),"captchaCode",captcha.get("answer")));}
    private ResponseEntity<JsonNode> requestRegistrationCode(String channel,String target){Map<String,String> captcha=captchaAnswer();return anonymousJson(HttpMethod.POST,"/api/auth/registration-code",Map.of("channel",channel,"target",target,"captchaKey",captcha.get("key"),"captchaCode",captcha.get("answer")));}
    private Map<String,Object> registrationBody(String username,String realName,String email,String phone,String password,String channel,String verificationId,String verificationCode){Map<String,String> captcha=captchaAnswer();Map<String,Object> body=new java.util.LinkedHashMap<>();body.put("username",username);body.put("realName",realName);body.put("email","EMAIL".equals(channel)?email:null);body.put("phone","PHONE".equals(channel)?phone:null);body.put("password",password);body.put("confirmPassword",password);body.put("verificationChannel",channel);body.put("verificationId",verificationId);body.put("verificationCode",verificationCode);body.put("captchaKey",captcha.get("key"));body.put("captchaCode",captcha.get("answer"));return body;}
    private Map<String,String> captchaAnswer(){JsonNode captcha=rest.getForObject("/api/auth/captcha",JsonNode.class);String key=captcha.at("/data/captchaKey").asText();return Map.of("key",key,"answer",redis.opsForValue().get("captcha:"+key));}
    private ResponseEntity<JsonNode> anonymousJson(HttpMethod method,String endpoint,Object body){HttpHeaders headers=new HttpHeaders();headers.setContentType(MediaType.APPLICATION_JSON);return rest.exchange(endpoint,method,new HttpEntity<>(body,headers),JsonNode.class);}
    private ResponseEntity<JsonNode> importUsers(String token,byte[] bytes,String fileName,String reason)throws Exception{MultiValueMap<String,Object> form=new LinkedMultiValueMap<>();form.add("file",new ByteArrayResource(bytes){@Override public String getFilename(){return fileName;}});form.add("reason",reason);HttpHeaders headers=authHeaders(token);headers.setContentType(MediaType.MULTIPART_FORM_DATA);headers.set("X-Step-Up-Token",issueStepUp(token,"PRIVILEGE",HttpMethod.POST,"/api/admin/users/import",Map.of("reason",reason,"size",bytes.length,"sha256",HexFormat.of().formatHex(java.security.MessageDigest.getInstance("SHA-256").digest(bytes)))));java.util.List<org.springframework.http.client.ClientHttpRequestInterceptor> interceptors=new java.util.ArrayList<>(rest.getRestTemplate().getInterceptors());rest.getRestTemplate().setInterceptors(java.util.List.of());try{return rest.exchange("/api/admin/users/import",HttpMethod.POST,new HttpEntity<>(form,headers),JsonNode.class);}finally{rest.getRestTemplate().setInterceptors(interceptors);}}
    private ResponseEntity<JsonNode> get(String endpoint,String token){return rest.exchange(endpoint,HttpMethod.GET,new HttpEntity<>(authHeaders(token)),JsonNode.class);}
    private ResponseEntity<JsonNode> request(HttpMethod method,String endpoint,String token,Object body){return authorizedJson(method,endpoint,token,body,Map.of());}
    private ResponseEntity<JsonNode> authorizedJson(HttpMethod method,String endpoint,String token,Object body,Map<String,String> extra){HttpHeaders headers=authHeaders(token);headers.setContentType(MediaType.APPLICATION_JSON);extra.forEach(headers::set);return rest.exchange(endpoint,method,new HttpEntity<>(body,headers),JsonNode.class);}
    private void installStepUpInterceptor(){rest.getRestTemplate().getInterceptors().add((request,body,execution)->{String path=request.getURI().getRawPath();HttpMethod method=request.getMethod();String purpose=stepUpPurpose(method,path);if(purpose!=null&&!request.getHeaders().containsKey("X-Step-Up-Token")){String authorization=request.getHeaders().getFirst(HttpHeaders.AUTHORIZATION);if(authorization!=null&&authorization.startsWith("Bearer ")){String accessToken=authorization.substring(7);String target=path+(request.getURI().getRawQuery()==null?"":"?"+request.getURI().getRawQuery());MediaType contentType=request.getHeaders().getContentType();Object payload=("PRIVILEGE".equals(purpose)||"EXPORT".equals(purpose)&&method==HttpMethod.POST)&&body.length>0&&contentType!=null&&MediaType.APPLICATION_JSON.includes(contentType)?mapper.readTree(body):null;request.getHeaders().set("X-Step-Up-Token",issueStepUp(accessToken,purpose,method,target,payload));}}return execution.execute(request,body);});}
    private String stepUpPurpose(HttpMethod method,String path){if(method==HttpMethod.GET&&(path.equals("/api/dashboard/report/export")||path.equals("/api/audits/export")||path.matches("^/api/datasets/\\d+/(export|export-package)$"))||method==HttpMethod.POST&&path.matches("^/api/datasets/\\d+/exports$"))return "EXPORT";if(method==HttpMethod.DELETE&&(path.matches("^/api/templates/\\d+$")||path.matches("^/api/files/\\d+$")||path.matches("^/api/datasets/\\d+$")||path.matches("^/api/datasets/\\d+/records/[^/]+$")||path.matches("^/api/business/modules/[^/]+/records/\\d+$")))return "DELETE";if((path.startsWith("/api/governance/")&&(method==HttpMethod.POST||method==HttpMethod.PUT||method==HttpMethod.DELETE))||(path.startsWith("/api/admin/users")&&(method==HttpMethod.POST||method==HttpMethod.PUT||method==HttpMethod.DELETE))||(method==HttpMethod.POST&&path.matches("^/api/admin/registrations/\\d+/review$"))||(method==HttpMethod.POST&&path.equals("/api/shares"))||(method==HttpMethod.DELETE&&path.matches("^/api/shares/\\d+$"))||(method==HttpMethod.POST&&path.matches("^/api/integrations/dead-letters/\\d+/retry$")))return "PRIVILEGE";return null;}
    private String issueStepUp(String token,String purpose,HttpMethod method,String target){return issueStepUp(token,purpose,method,target,null);}
    private String issueStepUp(String token,String purpose,HttpMethod method,String target,Object payload){ensureSecondaryCredential(token);HttpHeaders headers=authHeaders(token);headers.setContentType(MediaType.APPLICATION_JSON);Map<String,Object> request=new java.util.LinkedHashMap<>();request.put("purpose",purpose);request.put("method",method.name());request.put("target",target);request.put("secondaryPassword",stepUpCredentials(token).secondaryPassword());if(payload!=null)request.put("payload",payload);ResponseEntity<JsonNode> response=rest.exchange("/api/user/step-up",HttpMethod.POST,new HttpEntity<>(request,headers),JsonNode.class);assertEquals(200,response.getStatusCode().value(),String.valueOf(response.getBody()));return response.getBody().at("/data/token").asText();}
    private void ensureSecondaryCredential(String token){if(get("/api/user/profile",token).getBody().at("/data/secondaryPasswordSet").asBoolean())return;StepUpCredentials value=stepUpCredentials(token);HttpHeaders headers=authHeaders(token);headers.setContentType(MediaType.APPLICATION_JSON);ResponseEntity<JsonNode> response=rest.exchange("/api/user/secondary-password",HttpMethod.PUT,new HttpEntity<>(Map.of("currentPassword",value.loginPassword(),"newSecondaryPassword",value.secondaryPassword(),"confirmSecondaryPassword",value.secondaryPassword()),headers),JsonNode.class);assertEquals(200,response.getStatusCode().value(),String.valueOf(response.getBody()));}
    private StepUpCredentials stepUpCredentials(String token){try{JsonNode payload=mapper.readTree(java.util.Base64.getUrlDecoder().decode(token.split("\\.")[1]));return switch(payload.path("username").asText()){case "admin"->new StepUpCredentials(USER_PASSWORD,ADMIN_SECONDARY_PASSWORD);case "outside_reviewer"->new StepUpCredentials("Outside@2026E",OUTSIDE_SECONDARY_PASSWORD);case "reader"->new StepUpCredentials("Reader@2026D",READER_SECONDARY_PASSWORD);case "compliance_auditor"->new StepUpCredentials("Auditor@2026G",AUDITOR_SECONDARY_PASSWORD);case "reviewer"->new StepUpCredentials("Reviewer@2026C",REVIEWER_SECONDARY_PASSWORD);case "limited_operator"->new StepUpCredentials("Limited@2026K","852456");default->throw new IllegalStateException("No test secondary credential for "+payload.path("username").asText());};}catch(Exception ex){throw new IllegalStateException(ex);}}
    private HttpHeaders authHeaders(String token){HttpHeaders headers=new HttpHeaders();headers.setBearerAuth(token);return headers;}
    private HttpEntity<ByteArrayResource> filePart(byte[] bytes,String name,String contentType){HttpHeaders headers=new HttpHeaders();headers.setContentType(MediaType.parseMediaType(contentType));return new HttpEntity<>(new ByteArrayResource(bytes){@Override public String getFilename(){return name;}},headers);}
    private Map<String,byte[]> zipEntries(byte[] bytes)throws Exception{Map<String,byte[]> result=new java.util.LinkedHashMap<>();try(var input=new java.util.zip.ZipInputStream(new java.io.ByteArrayInputStream(bytes),StandardCharsets.UTF_8)){for(java.util.zip.ZipEntry entry;(entry=input.getNextEntry())!=null;){ByteArrayOutputStream output=new ByteArrayOutputStream();input.transferTo(output);result.put(entry.getName(),output.toByteArray());}}return result;}
    @SuppressWarnings("unchecked") private Map<String,Object> datasetBody(JsonNode dataset,long scope){Map<String,Object> body=new java.util.LinkedHashMap<>();body.put("name",dataset.path("name").asText());body.put("description",dataset.path("description").asText(""));body.put("category",dataset.path("category").asText(""));body.put("tags",dataset.path("tags").asText(""));body.put("recordCodePrefix",dataset.path("recordCodePrefix").asText(""));body.put("dataScopeId",scope);body.put("templateId",dataset.path("templateId").isNumber()?dataset.path("templateId").asLong():null);body.put("fieldDefinition",mapper.convertValue(dataset.path("fieldDefinition"),java.util.List.class));return body;}
    private String hmac(String secret,String value)throws Exception{Mac mac=Mac.getInstance("HmacSHA256");mac.init(new SecretKeySpec(secret.getBytes(StandardCharsets.UTF_8),"HmacSHA256"));return HexFormat.of().formatHex(mac.doFinal(value.getBytes(StandardCharsets.UTF_8)));}
    private HttpHeaders webhookHeaders(String timestamp,String key,String signature){HttpHeaders headers=new HttpHeaders();headers.setContentType(MediaType.APPLICATION_JSON);headers.set("X-Timestamp",timestamp);headers.set("X-Idempotency-Key",key);headers.set("X-Signature",signature);return headers;}
    private String integrationHmac(String secret,String systemCode,String timestamp,String key,String body)throws Exception{return hmac(secret,"RDP-HMAC-V1\nPOST\n/api/integrations/webhook/"+systemCode+"\n"+timestamp+"\n"+key+"\n"+body);}
    private String sha256(String value)throws Exception{return HexFormat.of().formatHex(java.security.MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8)));}
    private record StepUpCredentials(String loginPassword,String secondaryPassword){}
